chapters=[]
def add(title,body):chapters.append((title,body))
def original(i):
 s=base.pages[i]
 title=re.search(r'<h1>(.*?)</h1>',s).group(1)
 body=s.split('</h1>',1)[1]
 body=re.sub(r'<footer>.*?</footer></section>$','',body,flags=re.S)
 body=re.sub(r'<div class="kicker">.*?</div>','',body,flags=re.S)
 return title,body
originals=[original(i) for i in range(8)]
