chapters[1]=('Spis treści',toc)
logo=(ROOT/'frontend/assets/logo.svg').read_text()
styles='''@page{size:A4;margin:18mm 18mm 20mm}*{box-sizing:border-box}body{margin:0;font:10.4pt/1.5 "DejaVu Sans",sans-serif;color:#1d2b34;background:white}h1{font-size:24pt;line-height:1.18;letter-spacing:-.5px;margin:0 0 7mm;break-after:avoid}h2{font-size:13pt;line-height:1.3;color:#145c64;margin:6mm 0 2mm;break-after:avoid}p{margin:0 0 3.4mm;orphans:3;widows:3}li{margin-bottom:2mm}table{width:100%;border-collapse:collapse;margin:4mm 0;font-size:9.2pt;table-layout:fixed}td,th{padding:2.6mm;text-align:left;vertical-align:top;border-bottom:1px solid #dce3e6;overflow-wrap:anywhere}th{color:#145c64;background:#edf4f3}thead{display:table-header-group}tr{break-inside:avoid}table.api td:first-child{width:47%}table.api td:nth-child(2){width:18%}.chapter{break-before:page}.chapter:first-child{break-before:auto}.small{font-size:8.6pt;line-height:1.4;color:#526570}.note{padding:3mm 4mm;background:#edf4f3;border:1px solid #dce3e6;margin:4mm 0;font-size:9.3pt}.step{margin-bottom:4mm}.step b{color:#145c64}.feature{border-bottom:1px solid #dce3e6;padding-bottom:2mm}.cover{min-height:230mm;position:relative}.cover h1{font-size:38pt;padding-top:10mm}.cover-mark{position:absolute;right:0;top:8mm;width:13mm;height:21mm}.cover-mark svg{width:100%;height:100%}.lead{font-size:20pt;line-height:1.4;margin:10mm 0 7mm}.intro{font-size:12pt}.numbers{display:flex;gap:12mm;padding:5mm 0;border-top:1px solid #dce3e6;border-bottom:1px solid #dce3e6;margin:5mm 0}.numbers b{display:block;color:#145c64;font-size:21pt}.numbers span{font-size:9pt}.chart{width:100%;display:block;margin:4mm 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f0f3f4;padding:3mm;font:8.5pt/1.5 "DejaVu Sans Mono",monospace;break-inside:avoid}code{font:8.8pt "DejaVu Sans Mono",monospace;overflow-wrap:anywhere}.flow{text-align:center;background:#edf4f3;padding:3mm;font-weight:600;line-height:1.4}.flow span{color:#145c64}.toc{columns:2;column-gap:8mm}.toc a{display:block;color:#145c64;text-decoration:none;margin-bottom:3mm;font-size:9.6pt;break-inside:avoid}.endpoint h2{font-size:12pt}.endpoint{margin-bottom:7mm}a{color:#145c64}ul,ol{padding-left:5mm}footer{display:none}'''
body=''.join(f'<section class="chapter {"cover" if i==0 else ""}" id="chapter-{i}"><h1>{"" if i<2 else str(i-1)+". "}{E(title)}</h1>{content}</section>' for i,(title,content) in enumerate(chapters))
